const projectActivityReport = `-- name: ProjectActivityReport :many
WITH change_counts AS (
 SELECT c.project_id,COUNT(*)::bigint AS changes,
 COUNT(*) FILTER(WHERE current.status=$2::text)::bigint AS active_items,
 COUNT(*) FILTER(WHERE c.state IN ($3::text,$4::text,$5::text))::bigint AS open_changes,
 COUNT(*) FILTER(WHERE c.type='uplift' AND c.state=$4::text)::bigint AS open_uplifts
 FROM changes c LEFT JOIN runs current ON current.id=c.run_id AND current.project_id=c.project_id
 WHERE c.project_id=ANY($1::uuid[]) GROUP BY c.project_id
), run_counts AS (
 SELECT project_id,COUNT(*) FILTER(WHERE status=$6::text AND parent_run_id IS NULL)::bigint AS done_runs,
 COUNT(*) FILTER(WHERE status=$2::text)::bigint AS running_runs,MAX(updated_at) AS last_run_at
 FROM runs WHERE project_id=ANY($1::uuid[]) GROUP BY project_id
)
SELECT p.id,COALESCE(c.changes,0)::bigint AS changes,COALESCE(c.active_items,0)::bigint AS active_items,
 COALESCE(r.done_runs,0)::bigint AS done_runs,COALESCE(r.running_runs,0)::bigint AS running_runs,
 COALESCE(r.last_run_at,'epoch'::timestamptz)::timestamptz AS last_run_at,(r.last_run_at IS NOT NULL)::boolean AS has_last_run_at,
 COALESCE(c.open_changes,0)::bigint AS open_changes,COALESCE(c.open_uplifts,0)::bigint AS open_uplifts
FROM projects p LEFT JOIN change_counts c ON c.project_id=p.id LEFT JOIN run_counts r ON r.project_id=p.id
WHERE p.id=ANY($1::uuid[])
`

type ProjectActivityReportParams struct {
	ProjectIds      []ids.ID
	RunningStatus   string
	ProposedState   string
	InProgressState string
	LandingState    string
	DoneStatus      string
}

type ProjectActivityReportRow struct {
	ID           ids.ID
	Changes      int64
	ActiveItems  int64
	DoneRuns     int64
	RunningRuns  int64
	LastRunAt    time.Time
	HasLastRunAt bool
	OpenChanges  int64
	OpenUplifts  int64
}

func (q *Queries) ProjectActivityReport(ctx context.Context, arg ProjectActivityReportParams) ([]ProjectActivityReportRow, error) {
	rows, err := q.db.QueryContext(ctx, projectActivityReport,
		pq.Array(arg.ProjectIds),
		arg.RunningStatus,
		arg.ProposedState,
		arg.InProgressState,
		arg.LandingState,
		arg.DoneStatus,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ProjectActivityReportRow
	for rows.Next() {
		var i ProjectActivityReportRow
		if err := rows.Scan(
			&i.ID,
			&i.Changes,
			&i.ActiveItems,
			&i.DoneRuns,
			&i.RunningRuns,
			&i.LastRunAt,
			&i.HasLastRunAt,
			&i.OpenChanges,
			&i.OpenUplifts,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

